function stripNavigationQuotes(raw: string): string {
  return raw
    .replace(/^> \[⬅️.*?\n\n/s, '')
    .replace(/\n---\n\n> \[⬅️.*$/s, '')
    .replace(/^> \[🏠.*?\n\n/s, '')
    .replace(/\n---\n\n> \[🏠.*$/s, '')
    .trim();
}

function extractCardAndTutorial(markdown: string): { cardMarkdown: string; tutorialMarkdown: string; answerCode: string } {
  const cleaned = stripNavigationQuotes(markdown);
  let cardMarkdown = '';
  let rest = cleaned;

  const cardMatch = cleaned.match(/\n(> ### 💡 本日大白话速懂卡片.*?)(?=\n### 1\. 学习目标)/s);
  if (cardMatch) {
    cardMarkdown = cardMatch[1]
      .split('\n')
      .map(line => line.replace(/^> ?/, ''))
      .join('\n')
      .trim();
    rest = cleaned.replace(cardMatch[0], '\n');
  }

  let answerCode = '';
  const answerMatch = rest.match(/#### (?:第 \d 天练习参考答案|结业独立任务参考答案.*?)\n+(?:<details>\s*<summary>.*?<\/summary>\s*)?(```go\n.*?```|[\s\S]*?)(?:\n<\/details>)?$/s);
  if (answerMatch) {
    answerCode = answerMatch[1].replace(/<\/?details>|<summary>.*?<\/summary>/g, '').trim();
  }

  // Remove <details> HTML tags so AgentMarkdown renders cleanly without raw HTML tags
  const tutorialMarkdown = rest
    .replace(/<details>\s*<summary>(.*?)<\/summary>/g, '> **$1**')
    .replace(/<\/details>/g, '')
    .replace(/<\/?b>/g, '**')
    .trim();

  return { cardMarkdown, tutorialMarkdown, answerCode };
}

export async function readGoDayDetail(docsRoot: string, dayNumber: number): Promise<GoDayDetail> {
  const meta = GO_DAYS_META.find(item => item.day === dayNumber) || GO_DAYS_META[0]!;
  const filePath = path.join(docsRoot, 'docs', meta.docFile);
  let raw = '';
  try {
    raw = await fs.readFile(filePath, 'utf8');
  } catch {
    const steps = meta.checklist.map(item => `- ${item.text}`).join('\n');
    const exercises = meta.exercises.map(item => `- **${item.title}**　${item.description}`).join('\n');
    const files = GO_SANDBOX_SNAPSHOTS[meta.day === 7 ? 'day7-graduation' : `day${meta.day}`] || {};
    const answerCode = Object.entries(files).filter(([name]) => name.endsWith('.go'))
      .map(([name, content]) => `#### ${name}\n\n\`\`\`go\n${content.trimEnd()}\n\`\`\``).join('\n\n');
    return { ...meta, cardMarkdown: meta.goal, answerCode,
      tutorialMarkdown: `### 学习目标\n\n${meta.goal}\n\n### 练习步骤\n\n${steps}\n\n### 本日练习\n\n${exercises}\n\n### 交付成果\n\n${meta.deliverable}` };
  }
  const { cardMarkdown, tutorialMarkdown, answerCode } = extractCardAndTutorial(raw);
  return {
    ...meta,
    cardMarkdown,
    tutorialMarkdown,
    answerCode,
  };
}

export async function readGoGuideAndCheatSheet(docsRoot: string): Promise<{ guideMarkdown: string; cheatSheetMarkdown: string }> {
  let guideMarkdown = '';
  let cheatSheetMarkdown = '';
  try {
    guideMarkdown = await fs.readFile(path.join(docsRoot, 'README.md'), 'utf8');
  } catch {
    guideMarkdown = '# 《7 天上手 Go》通俗图解导读\n\n按顺序学习七章，每天阅读目标、修改课程代码并完成检查清单。前四天练习命令行任务管理，后三天加入 HTTP 接口、测试和并发安全。';
  }
  try {
    const rawCheat = await fs.readFile(path.join(docsRoot, 'docs', '08-结业验收与语法速查表.md'), 'utf8');
    cheatSheetMarkdown = stripNavigationQuotes(rawCheat);
  } catch {
    cheatSheetMarkdown = '# Go 核心语法与常用命令速查表\n\n- `go run .` 编译并运行当前模块\n- `go test -v -cover ./...` 运行测试并显示覆盖率\n- `go test -race ./...` 检查数据竞争\n- `go vet ./...` 运行静态检查\n- `gofmt -s -w .` 格式化 Go 源码';
  }
  return { guideMarkdown, cheatSheetMarkdown };
}
